    표8_상담적용: [
        {"상황":"성경 읽기가 형식적이 되어 하나님의 음성을 듣지 못하는 성도", "성경원리":"하나님의 말씀은 선지자에게 능동적으로 임하는 살아있는 계시이며, 성경은 오늘도 살아 역사하는 하나님의 말씀이다", "실제적용":"묵상법이나 렉시오 디비나 같은 깊이 있는 성경 읽기 방법을 소개하고, 말씀 속에서 하나님의 음성을 구하는 기도를 훈련한다"},
        {"상황":"하나님의 뜻을 분별하지 못해 혼란스러운 성도", "성경원리":"하나님은 선지자에게 상황에 맞는 구체적인 말씀을 주셨으며, 오늘도 성경과 성령을 통해 인도하신다", "실제적용":"성경의 원칙, 기도 속의 평안, 신뢰할 수 있는 멘토의 조언 세 가지를 통해 하나님의 뜻을 분별하는 방법을 안내한다"},
        {"상황":"설교나 성경공부가 감동이 없다고 느끼는 성도", "성경원리":"말씀이 임하는 것은 하나님의 주권이며, 동시에 듣는 자의 마음 자세도 중요하다", "실제적용":"말씀을 듣기 전 기도로 마음을 준비하고, 들은 말씀을 적용하는 실천을 통해 말씀의 능력을 경험하도록 돕는다"}
    ],
    표9_교차참조: [
        {"구절":"예레미야 1:4", "연결점":"여호와의 말씀이 내게 임하니라 같은 신탁 도입 공식의 사용", "구분":"구약"},
        {"구절":"호세아 1:1", "연결점":"여호와의 말씀이 호세아에게 임하니라 선지서의 표준적 계시 도입 표현", "구분":"구약"},
        {"구절":"사무엘상 3:21", "연결점":"여호와께서 실로에서 사무엘에게 여호와의 말씀으로 자기를 나타내시니라", "구분":"구약"},
        {"구절":"아모스 3:7", "연결점":"주 여호와께서는 자기의 비밀을 그의 종 선지자들에게 보이지 아니하시고는 결코 행하심이 없으시리라", "구분":"구약"},
        {"구절":"히브리서 1:1-2", "연결점":"옛적에 선지자들을 통하여 여러 부분과 여러 모양으로 말씀하신 하나님이 이 모든 날 마지막에 아들을 통하여 말씀하셨으니", "구분":"신약"},
        {"구절":"베드로후서 1:21", "연결점":"예언은 언제든지 사람의 뜻으로 낸 것이 아니요 오직 성령의 감동하심을 받은 사람들이 하나님께 받아 말한 것임이라", "구분":"신약"},
        {"구절":"요한복음 1:1", "연결점":"태초에 말씀이 계시니라 이 말씀이 하나님과 함께 계셨으니 이 말씀은 곧 하나님이시니라", "구분":"신약"},
        {"구절":"디모데후서 3:16", "연결점":"모든 성경은 하나님의 감동으로 된 것으로 교훈과 책망과 바르게 함과 의로 교육하기에 유익하니라", "구분":"신약"}
    ]
