    표8_상담적용: [
        {"상황":"삶의 방향과 의미를 잃은 성도", "성경원리":"하나님이 나의 하나님이 되시고 그리스도가 나의 왕이 되시는 관계 속에서 삶의 의미와 방향이 회복된다", "실제적용":"하나님과의 관계 회복을 최우선 과제로 설정하고 매일 말씀과 기도를 통해 하나님의 통치를 경험하도록 구체적 계획을 세운다"},
        {"상황":"세상의 권위와 하나님의 권위 사이에서 갈등하는 성도", "성경원리":"궁극적 왕은 그리스도이시며 모든 세상적 권위는 그분의 권위 아래 있다", "실제적용":"그리스도의 왕 되심을 삶의 모든 영역에 적용하는 방법을 함께 모색하며 세상적 가치와 하나님 나라의 가치를 분별하도록 돕는다"},
        {"상황":"하나님의 약속을 의심하는 성도", "성경원리":"나 여호와의 말씀이니라는 선언은 하나님의 약속이 반드시 이루어질 것임을 보증한다", "실제적용":"성경에서 이미 이루어진 약속들을 함께 살펴보며 하나님의 신실하심에 대한 확신을 세우도록 돕는다"}
    ],
    표9_교차참조: [
        {"구절":"출애굽기 6:7", "연결점":"나는 너희 하나님이 되리라 너희가 알리라 나는 너희 하나님 여호와라", "구분":"구약"},
        {"구절":"사무엘하 7:14-16", "연결점":"나는 그에게 아버지가 되고 그는 내게 아들이 되리라 그의 나라가 영원히 견고하리라", "구분":"구약"},
        {"구절":"예레미야 30:9", "연결점":"그들은 그들의 하나님 여호와와 내가 그들을 위하여 세울 그들의 왕 다윗을 섬기리라", "구분":"구약"},
        {"구절":"호세아 3:5", "연결점":"그 후에 이스라엘 자손이 돌아와서 그들의 하나님 여호와와 그들의 왕 다윗을 구하리라", "구분":"구약"},
        {"구절":"누가복음 1:32-33", "연결점":"주 하나님이 그 조상 다윗의 왕위를 주시리니 그가 영원히 야곱의 집에 왕 노릇 하시리라", "구분":"신약"},
        {"구절":"요한복음 1:14", "연결점":"말씀이 육신이 되어 우리 가운데 거하시매 우리가 그의 영광을 보니 은혜와 진리가 충만하더라", "구분":"신약"},
        {"구절":"빌립보서 2:6-11", "연결점":"근본 하나님의 본체시나 종의 형체를 가지사 모든 무릎이 꿇어 주라 시인하게 되리라", "구분":"신약"},
        {"구절":"요한계시록 21:3", "연결점":"보라 하나님의 장막이 사람들과 함께 있으매 하나님이 그들의 하나님이 되시리라", "구분":"신약"}
    ]
