    표8_상담적용: [
        {"상황":"마음 속에 쌓인 분노와 원망이 악한 생각으로 발전할까 두려운 성도", "성경원리":"악한 꾀는 마음에서 나온다 - 그러나 하나님은 새 마음을 주신다(겔 36:26)", "실제적용":"마음 속 분노의 근원을 탐색하고, 하나님께 마음을 열어 정결하게 하는 기도를 드리도록 안내"},
        {"상황":"자신의 불순한 동기를 발견하고 혼란스러운 성도", "성경원리":"하나님은 마음 속 생각도 아신다 - 마음을 숨기려 하지 말고 하나님께 열어 보이라", "실제적용":"시편 139편을 함께 읽고, 하나님께 마음을 검사받는 기도를 드리도록 도움"},
        {"상황":"다른 사람의 악한 의도로 인해 상처받은 성도", "성경원리":"하나님은 악한 꾀도 아시고 심판하신다 - 억울함을 하나님께 맡기라", "실제적용":"하나님이 공의로운 심판자이심을 확인하고, 억울함을 하나님께 맡기며 용서의 여정을 시작하도록 안내"}
    ],
    표9_교차참조: [
        {"구절":"예레미야 17:9-10", "연결점":"만물보다 거짓되고 부패한 것은 마음이라... 나 여호와는 심장을 살피며 - 악한 꾀의 원천과 하나님의 전지하심", "구분":"구약"},
        {"구절":"마가복음 7:21-23", "연결점":"마음에서 나오는 것들이 사람을 더럽힌다 - 예수님이 확인하신 악의 내적 원천", "구분":"신약"},
        {"구절":"잠언 19:21", "연결점":"사람의 마음에는 많은 계획이 있어도 오직 여호와의 뜻만이 완전히 서리라 - 악한 꾀의 실패", "구분":"구약"},
        {"구절":"시편 139:1-4", "연결점":"내가 앉고 일어섬을 아시고 내가 생각을 품기도 전에 아시나이다 - 하나님의 전지하심", "구분":"구약"},
        {"구절":"히브리서 4:12-13", "연결점":"마음의 생각과 뜻을 판단하며... 만물이 그의 눈앞에 벌거벗은 것 같이 드러나느니라 - 마음을 아시는 하나님", "구분":"신약"},
        {"구절":"에스더 7:10", "연결점":"하만이 모르드개를 달려고 만든 나무에 하만을 달리라 - 악한 꾀가 자기에게 돌아오는 패턴", "구분":"구약"},
        {"구절":"잠언 4:23", "연결점":"생명의 근원이 마음에서 남이라 - 마음을 지키는 것이 모든 보호의 근원", "구분":"구약"},
        {"구절":"시편 51:10", "연결점":"내 속에 정한 마음을 창조하시고 - 악한 꾀 대신 정결한 마음을 구하는 기도", "구분":"구약"}
    ]
